"""Model evaluation report loader and validation metrics provider for GeoVision.

Provides auditable performance metrics (Precision, Recall, F1, mAP50, mAP50-95,
confusion matrix, and error analysis) without fabricating accuracy numbers.
"""

from __future__ import annotations

import json
from pathlib import Path
from typing import Any

# Default path to evaluation report JSON generated by the Colab training pipeline
DEFAULT_EVALUATION_REPORT_PATH = (
    Path(__file__).resolve().parents[4] / "training" / "geovision" / "evaluation" / "evaluation_report.json"
)

